 @BeforeEach void seed(){f=new PurchaseReturnTest();f.setup();parent=f.create(5);f.returns.approve("QM",parent,f.review(),"reviewer");eid=db.queryForObject("SELECT id FROM purchase_return_execution WHERE return_id=?",Long.class,parent);db.update("UPDATE purchase_return SET state='APPROVED',stock_reserved=1,outbound_mode=1,dispatch_state='ACCEPTED' WHERE id=?",parent);db.update("UPDATE purchase_return_execution SET outbound_mode=1,stock_ready=1,dispatch_state='ACCEPTED' WHERE id=?",eid);line=((List<Map<String,Object>>)f.returns.detail("QM",parent).get("execution_lines")).get(0);lid=((Number)line.get("id")).longValue();}
 Map<String,Object> row(long id,int q){return m("line_key",id,"sku_sn",line.get("sku_sn"),"batch_code",line.get("batch_code"),"inventory_type","ZP","quantity",q);}
 Map<String,Object> receipt(String msg,int q,boolean end){return m("message_id",msg,"complete",end,"status",end?"DELIVERED":"PARTDELIVERED","total_lines",1,"lines",Collections.singletonList(row(lid,q)));}
 void accept(Map<String,Object>r){f.fulfillment.accept("QM",eid,r,0,true);}
 void post(){f.returns.process("QM",parent);}
 Map<String,Object> cmd(){Map<String,Object>c=f.current(parent);c.putAll(m("request_key",UUID.randomUUID().toString(),"reason","供应商同意继续原计划","evidence","仓库原始装箱记录"));return c;}
 Map<String,Object>pack(String code,int q){return m("package_code",code,"standard_id",1,"carrier_code","SF","waybill","ONE-WAYBILL","items",Collections.singletonList(m("sku_sn",line.get("sku_sn"),"line_key",lid,"quantity",q)));}
 @Test void incrementalMessagesAndSameWaybillMultipleParcelsPostOnlyOnce(){Map<String,Object>a=receipt("M1",2,false);a.put("packages",Arrays.asList(pack("P1",1),pack("P2",1)));accept(a);accept(a);post();Map<String,Object>b=receipt("M2",3,true);b.put("packages",Collections.singletonList(pack("P3",3)));accept(b);post();post();Map<String,Object>d=f.returns.detail("QM",parent);assertEquals(5L,d.get("posted_quantity"));assertEquals(3,((List)d.get("parcels")).size());assertEquals(3,((List)d.get("parcel_allocations")).size());assertEquals("COMPLETED",d.get("state"));verify(f.stock,times(2)).execute(eq("QM"),eq("post"),anyMap());}
 @Test void changedMessageCannotConsumeAgain(){Map<String,Object>a=receipt("M1",2,false);accept(a);post();assertThrows(IllegalArgumentException.class,()->accept(receipt("M1",1,false)));assertEquals(2L,f.returns.detail("QM",parent).get("posted_quantity"));}
 @Test void partialFinalContinuesInSameCGTAndReusesHold(){accept(receipt("M1",2,true));post();Map<String,Object>cmd=cmd();f.returns.continueRemaining("QM",parent,cmd,"tester");post();f.returns.continueRemaining("QM",parent,cmd,"tester");assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM purchase_return",Integer.class));assertEquals(2,db.queryForObject("SELECT COUNT(*) FROM purchase_return_execution",Integer.class));assertEquals("EXISTING",db.queryForObject("SELECT hold_action FROM purchase_return_execution WHERE sequence_no=2",String.class));verify(f.stock,never()).execute(eq("QM"),eq("release"),anyMap());verify(f.stock,never()).execute(eq("QM"),eq("rehold"),anyMap());}
 @Test void restoredReleasedRemainderRequiresOwnApproval(){accept(receipt("M1",2,true));post();Map<String,Object>stop=cmd();f.returns.cancel("QM",parent,stop,"tester");post();Map<String,Object>restore=cmd();f.returns.continueRemaining("QM",parent,restore,"tester");long request=db.queryForObject("SELECT id FROM purchase_return_execution_request",Long.class);assertEquals("REVIEW",db.queryForObject("SELECT state FROM purchase_return_execution_request",String.class));verify(f.stock,never()).execute(eq("QM"),eq("rehold"),anyMap());db.update("UPDATE purchase_return SET outbound_mode=2 WHERE id=?",parent);f.fulfillment.restoreApprove("QM",parent,request,f.current(parent),"reviewer");post();post();verify(f.stock,times(1)).execute(eq("QM"),eq("release"),anyMap());verify(f.stock,times(1)).execute(eq("QM"),eq("rehold"),anyMap());assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM purchase_return",Integer.class));assertEquals(5L,f.returns.detail("QM",parent).get("posted_quantity"));}
 @Test void restoreRechecksOriginalReceiptClaims(){accept(receipt("M1",2,true));post();f.returns.cancel("QM",parent,cmd(),"tester");post();f.returns.continueRemaining("QM",parent,cmd(),"tester");long other=f.create(7);f.returns.approve("QM",other,f.review(),"other");long request=db.queryForObject("SELECT id FROM purchase_return_execution_request",Long.class);db.update("UPDATE purchase_return SET outbound_mode=2 WHERE id=?",parent);assertThrows(IllegalArgumentException.class,()->f.fulfillment.restoreApprove("QM",parent,request,f.current(parent),"reviewer"));assertEquals("CANCELED",f.returns.detail("QM",parent).get("state"));}
 @Test void concurrentContinuationCreatesOneExecution()throws Exception{accept(receipt("M1",2,true));post();Map<String,Object>a=cmd(),b=cmd();ExecutorService pool=Executors.newFixedThreadPool(2);try{List<Callable<Boolean>>jobs=new ArrayList<>();for(Map<String,Object>c:Arrays.asList(a,b))jobs.add(()->{try{f.returns.continueRemaining("QM",parent,c,"tester");return true;}catch(Exception e){return false;}});int wins=0;for(Future<Boolean>r:pool.invokeAll(jobs))if(r.get())wins++;assertEquals(1,wins);post();assertEquals(2,db.queryForObject("SELECT COUNT(*) FROM purchase_return_execution",Integer.class));}finally{pool.shutdownNow();}}
 @Test void cumulativeSnapshotsUseVersionAndDeltaAndIgnoreOld(){db.update("UPDATE purchase_return_execution SET quantity_mode='CUMULATIVE' WHERE id=?",eid);Map<String,Object>a=receipt("V1",2,false);a.put("snapshot_version",1);accept(a);post();Map<String,Object>b=receipt("V3",5,true);b.put("snapshot_version",3);accept(b);post();Map<String,Object>old=receipt("LATEV2",3,false);old.put("snapshot_version",2);accept(old);post();assertEquals(5L,f.returns.detail("QM",parent).get("posted_quantity"));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM purchase_return_message WHERE state='IGNORED'",Integer.class));assertEquals(3L,db.queryForObject("SELECT quantity FROM purchase_return_event ORDER BY id DESC LIMIT 1",Long.class));}
