 long secondLine(){long root=((Number)line.get("return_line_id")).longValue();long second=db.queryForObject("SELECT MAX(id)+1 FROM purchase_return_line",Long.class);db.update("INSERT INTO purchase_return_line(company_code,return_id,source_key,ticket_sn,sku_sn,goods_name,stock_unit,batch_code,inventory_type,quantity,source_quantity,purchase_price) SELECT company_code,return_id,CONCAT(source_key,'X'),ticket_sn,sku_sn,goods_name,stock_unit,CONCAT(batch_code,'X'),inventory_type,1,source_quantity,purchase_price FROM purchase_return_line WHERE id=?",root);second=db.queryForObject("SELECT MAX(id) FROM purchase_return_line",Long.class);db.update("INSERT INTO purchase_return_execution_line(company_code,return_id,execution_id,return_line_id,quantity) VALUES('QM',?,?,?,1)",parent,eid,second);return db.queryForObject("SELECT MAX(id) FROM purchase_return_execution_line",Long.class);}
 @Test void fragmentsWaitForAllDeclaredRowsAndReplayDoesNotDoubleCount(){long second=secondLine();db.update("UPDATE purchase_return_execution SET fragment_mode='SPLIT' WHERE id=?",eid);Map<String,Object>a=receipt("SPLIT1",1,false);a.put("total_lines",2);accept(a);accept(a);assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM purchase_return_event",Integer.class));Map<String,Object>b=receipt("SPLIT1",1,false);b.put("total_lines",2);Map<String,Object>r=row(second,1);r.put("batch_code",line.get("batch_code")+"X");b.put("lines",Collections.singletonList(r));accept(b);post();assertEquals(2L,f.returns.detail("QM",parent).get("posted_quantity"));assertEquals(2,db.queryForObject("SELECT part_count FROM purchase_return_message",Integer.class));verify(f.stock,times(1)).execute(eq("QM"),eq("post"),anyMap());}
 @Test void incompleteFragmentBlocksStopAndNewExecution(){secondLine();db.update("UPDATE purchase_return_execution SET fragment_mode='SPLIT' WHERE id=?",eid);Map<String,Object>a=receipt("M1",1,false);a.put("total_lines",2);accept(a);f.returns.cancel("QM",parent,cmd(),"tester");post();assertEquals("CANCELING",f.returns.detail("QM",parent).get("state"));assertTrue(f.returns.detail("QM",parent).get("last_error").toString().contains("完整"));verify(f.stock,never()).execute(eq("QM"),eq("release"),anyMap());}
 @Test void parcelSupplementAndSupplierBindingDoNotPostInventoryTwice(){accept(receipt("M1",2,true));post();Map<String,Object>s=f.supplier(parent,"REFUSE",2);f.returns.supplierReceipt("QM",parent,s,"tester");Map<String,Object>metadata=cmd();metadata.putAll(pack("SUPPLEMENT",2));metadata.put("execution_id",eid);f.parcels.supplement("QM",parent,metadata,"tester");f.parcels.supplement("QM",parent,metadata,"tester");Map<String,Object>d=f.returns.detail("QM",parent);long source=((Number)((Map)((List)d.get("supplier_sources")).get(0)).get("id")).longValue(),allocation=((Number)((Map)((List)d.get("parcel_allocations")).get(0)).get("id")).longValue();Map<String,Object>bind=cmd();bind.put("lines",Collections.singletonList(m("supplier_line_id",source,"allocation_id",allocation,"quantity",2)));f.parcels.bindSupplier("QM",parent,bind,"tester");f.parcels.bindSupplier("QM",parent,bind,"tester");assertEquals(2L,db.queryForObject("SELECT supplier_refused_quantity FROM purchase_return_line WHERE return_id=?",Long.class,parent));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM purchase_return_supplier_line",Integer.class));verify(f.stock,times(1)).execute(eq("QM"),eq("post"),anyMap());verify(f.stock,never()).execute(eq("QM"),eq("recover"),anyMap());}
