 @Test void eachRefusalSourceCapsReclaimEvenForSameRootLine(){accept(receipt("M1",5,true));post();f.returns.supplierReceipt("QM",parent,f.supplier(parent,"REFUSE",2),"tester");f.returns.supplierReceipt("QM",parent,f.supplier(parent,"REFUSE",1),"tester");List<Map<String,Object>>sources=(List<Map<String,Object>>)f.returns.detail("QM",parent).get("supplier_sources");Map<String,Object>c=cmd();c.putAll(m("standard_id",1,"carrier_code","SF","waybill","REFUSAL-RETURN","lines",Arrays.asList(m("supplier_source_id",sources.get(0).get("id"),"quantity",1),m("supplier_source_id",sources.get(1).get("id"),"quantity",2))));PurchaseReturnReclaims reclaims=f.reclaims();long reclaim=reclaims.create("QM",parent,c,"tester");reclaims.approve("QM",reclaim,m("control_version",1),"reviewer");assertEquals(2,((List)reclaims.detail("QM",reclaim).get("lines")).size());Map<String,Object>extra=cmd();extra.putAll(m("standard_id",1,"carrier_code","SF","waybill","REFUSAL-EXTRA","lines",Collections.singletonList(m("supplier_source_id",sources.get(0).get("id"),"quantity",1))));assertThrows(IllegalArgumentException.class,()->reclaims.create("QM",parent,extra,"tester"));}
