 @Test void ambiguousSameSkuParcelsRequireExplicitOriginalBatch(){long second=secondLine();Map<String,Object>a=receipt("M1",2,true);Map<String,Object>r=row(second,1);r.put("batch_code",line.get("batch_code")+"X");a.put("lines",Arrays.asList(row(lid,2),r));a.put("total_lines",2);a.put("packages",Collections.singletonList(m("package_code","AMBIGUOUS","items",Collections.singletonList(m("sku_sn",line.get("sku_sn"),"quantity",2)))));accept(a);post();Map<String,Object>d=f.returns.detail("QM",parent);assertEquals(0,((List)d.get("parcel_allocations")).size());Map<String,Object>parcel=((List<Map<String,Object>>)d.get("parcels")).get(0),item=((List<Map<String,Object>>)parcel.get("items")).get(0);assertEquals("REVIEW",parcel.get("content_state"));Map<String,Object>c=cmd();c.put("lines",Collections.singletonList(m("item_id",item.get("id"),"execution_line_id",lid,"quantity",2)));f.parcels.allocate("QM",parent,c,"tester");f.parcels.allocate("QM",parent,c,"tester");assertEquals(1,((List)f.returns.detail("QM",parent).get("parcel_allocations")).size());verify(f.stock,times(1)).execute(eq("QM"),eq("post"),anyMap());}
