 @Test void supplierCanBindSameParcelInSeveralCommandsWithoutRecountingReceipt(){Map<String,Object>a=receipt("M1",3,true);a.put("packages",Collections.singletonList(pack("P1",3)));accept(a);post();f.returns.supplierReceipt("QM",parent,f.supplier(parent,"REFUSE",3),"tester");long allocation=db.queryForObject("SELECT id FROM purchase_return_parcel_allocation",Long.class),source=db.queryForObject("SELECT id FROM purchase_return_supplier_line",Long.class);for(int i=0;i<3;i++){Map<String,Object>c=cmd();c.put("lines",Collections.singletonList(m("supplier_line_id",source,"allocation_id",allocation,"quantity",1)));f.parcels.bindSupplier("QM",parent,c,"tester");f.parcels.bindSupplier("QM",parent,c,"tester");}assertEquals(3L,db.queryForObject("SELECT quantity FROM purchase_return_supplier_parcel",Long.class));assertEquals(3,db.queryForObject("SELECT COUNT(*) FROM purchase_return_metadata_command WHERE payload_json IS NOT NULL",Integer.class));assertEquals(3L,db.queryForObject("SELECT supplier_refused_quantity FROM purchase_return_line WHERE return_id=?",Long.class,parent));Map<String,Object>over=cmd();over.put("lines",Collections.singletonList(m("supplier_line_id",source,"allocation_id",allocation,"quantity",1)));assertThrows(IllegalArgumentException.class,()->f.parcels.bindSupplier("QM",parent,over,"tester"));}
