 @Test void unifiedTasksLocateMissingParcelsRestoreReviewAndSupplierGoods(){accept(receipt("M1",2,true));post();SupplychainOperations tasks=new SupplychainOperations();org.springframework.test.util.ReflectionTestUtils.setField(tasks,"db",context.getBean(WmsStore.class));Map<String,String>q=new HashMap<>();q.put("number",f.returns.detail("QM",parent).get("return_sn").toString());for(String issue:Arrays.asList("PARCEL","SUPPLIER")){q.put("issue",issue);assertEquals(1L,tasks.query("QM",q).get("total"));}f.returns.cancel("QM",parent,cmd(),"tester");post();f.returns.continueRemaining("QM",parent,cmd(),"tester");q.put("issue","RESTORE");Map<String,Object>result=tasks.query("QM",q);assertEquals(1L,result.get("total"));Map<String,Object>row=((List<Map<String,Object>>)result.get("rows")).get(0);assertEquals(parent,((Number)row.get("document_id")).longValue());assertEquals("purchaseReturn",row.get("kind"));}
