 @Test void recoveryCheckExplainsOtherDocumentAndExactSourceShortageWithoutMutation(){long request=restoreRequest(),other=f.create(7);f.returns.approve("QM",other,f.review(),"other");balance(1);Map<String,Object>before=f.current(parent),check=f.fulfillment.restoreCheck("QM",parent,request),l=((List<Map<String,Object>>)check.get("lines")).get(0);assertEquals(10L,((Number)l.get("source_quantity")).longValue());assertEquals(2L,l.get("own_posted_quantity"));assertEquals(7L,l.get("other_claimed_quantity"));assertEquals(1L,l.get("source_available_quantity"));assertEquals(3L,l.get("required_quantity"));assertEquals(2L,l.get("source_shortage_quantity"));assertEquals(1L,l.get("batch_available_quantity"));assertEquals(false,check.get("can_approve"));Map<String,Object>occupying=((List<Map<String,Object>>)l.get("claimants")).get(0);assertEquals(other,((Number)occupying.get("return_id")).longValue());assertEquals(7L,occupying.get("unexecuted_claim_quantity"));assertEquals(before,f.current(parent));assertEquals("CANCELED",f.returns.detail("QM",parent).get("state"));verify(f.stock,never()).execute(eq("QM"),eq("rehold"),anyMap());}
