 @Test void recoveryPreviewDoesNotTreatUnknownInventoryAsZeroOrAllowApproval(){long request=restoreRequest();when(f.stock.balances(anyString(),anyList())).thenReturn(com.ruoyi.common.core.domain.R.fail("库存查询失败"));Map<String,Object>check=f.fulfillment.restoreCheck("QM",parent,request),l=((List<Map<String,Object>>)check.get("lines")).get(0);assertEquals(true,check.get("source_ok"));assertEquals(false,check.get("can_approve"));assertEquals(false,check.get("inventory_checked"));assertEquals(false,l.get("inventory_known"));assertTrue(check.get("inventory_error").toString().contains("未查到"));}
